BEGIN
    IF TG_OP = 'INSERT' THEN
        IF (NEW.verified OR NEW.source = 'mb_resolve') AND NEW.role IN ('main', 'alt', 'demo') THEN
            UPDATE artists
            SET has_sc_account = true
            WHERE id = NEW.artist_id
              AND NOT has_sc_account;
        END IF;
        RETURN NULL;
    END IF;

    UPDATE artists
    SET has_sc_account = EXISTS (SELECT 1
                                 FROM artist_sc_accounts AS account
                                 WHERE account.artist_id = OLD.artist_id
                                   AND (account.verified OR account.source = 'mb_resolve')
                                   AND account.role IN ('main', 'alt', 'demo'))
    WHERE id = OLD.artist_id;
    RETURN NULL;
END;

BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.star_due_watch AS watch
        WHERE watch.watched_at > now() - interval '1 day'
    ) THEN
        RETURN NULL;
    END IF;
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.star_due_marks (sc_track_id)
        SELECT star.sc_track_id
        FROM public.star_track_tiers AS star
        WHERE star.sc_track_id = NEW.sc_track_id;
        RETURN NULL;
    END IF;
    INSERT INTO public.star_due_marks (sc_track_id)
    SELECT star.sc_track_id
    FROM public.star_track_tiers AS star
    WHERE star.sc_track_id = OLD.sc_track_id;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.sc_track_id IS DISTINCT FROM OLD.sc_track_id THEN
            INSERT INTO public.star_due_marks (sc_track_id)
            SELECT star.sc_track_id
            FROM public.star_track_tiers AS star
            WHERE star.sc_track_id = NEW.sc_track_id;
        END IF;
    END IF;
    RETURN NULL;
END

