BEGIN
    NEW.fts := to_tsvector(
        'simple',
        coalesce(NEW.plain_text, '') || ' '
        || regexp_replace(coalesce(NEW.synced_lrc, ''), '\[[0-9:.]+\]', ' ', 'g')
    );
    RETURN NEW;
END

